import os, json, re
from pathlib import Path

def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        return {}

    base = str(Path(session_dir).parent)
    sessions_path = base + '/sessions/' + os.path.basename(session_dir) + '.jsonl'

    try:
        with open(sessions_path, 'r') as f:
            content = f.read()
    except Exception as e:
        print(f"Error: {e}")
        return {}

    grids = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*\n', content):
        key = m[1]
        h, w = int(m[2]), int(m[3])
        grid_text = '\n'.join(content[m.end():].split('\n')[:h])
        rows = [grid_text.split()]
        # Validate and store
        valid = len(rows) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in rows)
        if valid:
            grids[key] = [[int(x) for x in r] for r in rows]

    return grids

